def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None
    visited = set()
    path_stack = []

    def backtrack(path):
        # Reconstruct and return path from stack
        while path_stack:
            path_stack.pop()
        while path:
            path_stack.append(path.pop())
        return path_stack

    def dfs(node, goal):
        if node == goal:
            return path_stack + [node]
        visited.add(node)
        path_stack.append(node)
        for neighbour in graph[node]:
            if neighbour not in visited:
                dfs(neighbour, goal)
        return backtrack(path_stack)

    return dfs(start, goal)
