def find_path(graph, start, goal):
    # Initialize stack for DFS
    stack = []  
    # Initialize visited set
    visited = set()

    # Push start node onto stack
    stack.append((start, [start]))  # (path, path_stack)

    while stack:  
        (node, path) = stack.pop()  
        if node not in visited:  
            visited.add(node)  
            if node == goal:  
                return path  # found the goal, return the path
            for neighbor in graph[node]:  
                if neighbor not in visited:  
                    stack.append((neighbor, path + [neighbor]))  # push neighbor to stack with updated path

    # If the goal is unreachable, return None
    return None
